<?php require __DIR__.'/config/bootstrap.php'; ?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>注册 · LinguaX</title><link rel="stylesheet" href="assets/css/app.css"></head><body><div class="auth card"><div class="brand">Lingua<span>X</span></div><h1>创建账户</h1><p>注册即开始 1 小时免费体验。</p><form id="form"><input name="name" placeholder="姓名"><input name="email" type="email" placeholder="邮箱" required><input name="password" type="password" placeholder="密码（至少6位）" required><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf())?>"><button class="primary">注册</button></form><div id="msg"></div><a href="login.php">已有账户？登录</a></div><script>form.onsubmit=async e=>{e.preventDefault();let r=await fetch('api/auth.php?action=register',{method:'POST',body:new FormData(form)});let j=await r.json();if(j.ok)location=j.redirect;else msg.textContent=j.message}</script></body></html>
